**Before** `.expo/types/router.d.ts`
```typescript
import type { ReactNode } from 'react';
import type { TextProps, GestureResponderEvent } from 'react-native';

export namespace ExpoRouter {
  type StaticRoutes = `/` | `/(latest)` | `/(tabs)` | `/_sitemap` | `/article` | `/category` | `/debug`;
  type DynamicRoutes<T extends string> = `/${CatchAllRoutePart<T>}` | `/${SingleRoutePart<T>}`;
  type DynamicRouteTemplate = `/[...unmatched]` | `/[id]`;
```

